--------------------------------------------------------------------------------
                    --TABLA PARA ARCHIVOS_POLIZAS_AUD--
--------------------------------------------------------------------------------
DROP PUBLIC SYNONYM ARCHIVOS_POLIZAS_AUD;

CREATE TABLE SICAS_OC.ARCHIVOS_POLIZAS_AUD (
    "ID"                    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY 
                            MINVALUE 1 MAXVALUE 9999999999999999999999999999 
                            INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE 
                            NOT NULL ENABLE,                    -- Identificador único de la auditoría
    "IDARCHIVO_POLIZA"      NUMBER,                             -- ID del archivo original en ARCHIVOS_POLIZAS
    "IDPOLIZA"              NUMBER(14,0) NOT NULL ENABLE,       -- Identificador de la póliza asociada
    "CODEMPRESA"            NUMBER DEFAULT 1 NOT NULL ENABLE,   -- Código de la empresa
    "CODCIA"                NUMBER DEFAULT 1 NOT NULL ENABLE,   -- Código de la compañía
    "VERSION"               NUMBER NOT NULL ENABLE,             -- Número de versión del archivo auditado
    "ACCION"                VARCHAR2(20),                       -- Acción realizada 
    "CLV_DOCUMENTO_GRUPO"   VARCHAR2(5),                        -- Clave del grupo de documentos
    "CLV_DOCUMENTO"         VARCHAR2(5),                        -- Clave del tipo de documento
    "COMENTARIOS"           VARCHAR2(4000),                     -- Comentarios asociados al archivo
    "ARCHIVO_BLOB"          BLOB,                               -- Contenido binario del archivo
    "NOMBRE_ARCHIVO"        VARCHAR2(255),                      -- Nombre del archivo
    "FILE_MIME_TYPE"        VARCHAR2(255),                      -- Tipo MIME del archivo
    "FILE_CHARSET"          VARCHAR2(255),                      -- Juego de caracteres del archivo
    "BLOB_LAST_UPDATE"      DATE,                               -- Fecha de última modificación del archivo BLOB
    "CREATED"               DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                       -- Fecha de creación del registro de auditoría
    "CREATED_BY"            VARCHAR2(50) DEFAULT COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'),USER) NOT NULL ENABLE, -- Usuario que creó el registro
    "UPDATED"               DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                       -- Fecha de última modificación
    "UPDATED_BY"            VARCHAR2(50) DEFAULT COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'),USER) NOT NULL ENABLE  -- Usuario que actualizó el registro
) TABLESPACE TS_SICASOC;

--ÍNDICES
CREATE UNIQUE INDEX SICAS_OC.ARCHIVOS_POLIZAS_AUD_INDX ON SICAS_OC.ARCHIVOS_POLIZAS_AUD (ID,CODCIA,CODEMPRESA) TABLESPACE IDX_SICASOC;
/

--PRIMARY KEY
ALTER TABLE SICAS_OC.ARCHIVOS_POLIZAS_AUD ADD CONSTRAINT PK_ARCHIVOS_POLIZAS_AUD PRIMARY KEY (ID,CODCIA,CODEMPRESA) USING INDEX;
ALTER TABLE SICAS_OC.ARCHIVOS_POLIZAS_AUD ADD CONSTRAINT FK_ARCHIVOS_POLIZAS_AUD_ARCHIVOS_POLIZAS FOREIGN KEY (IDARCHIVO_POLIZA) REFERENCES ARCHIVOS_POLIZAS (ID);
/

--GRANT
GRANT SELECT, INSERT, UPDATE, DELETE, ALTER ON SICAS_OC.ARCHIVOS_POLIZAS_AUD TO ROL_MODIFICA_SICAS;
GRANT SELECT ON SICAS_OC.ARCHIVOS_POLIZAS_AUD TO ROL_CONSULTA_SICAS;
/

--SINÓNIMO
CREATE OR REPLACE PUBLIC SYNONYM ARCHIVOS_POLIZAS_AUD FOR SICAS_OC.ARCHIVOS_POLIZAS_AUD;

--##COMENTARIOS DESCRIPTIVOS
COMMENT ON TABLE SICAS_OC.ARCHIVOS_POLIZAS_AUD                       IS 'Tabla de auditoría para el historial de archivos asociados a pólizas';

COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.ID                   IS 'Identificador único de la auditoría';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.IDARCHIVO_POLIZA     IS 'ID del archivo original en ARCHIVOS_POLIZAS';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.IDPOLIZA             IS 'Identificador de la póliza asociada';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.CODEMPRESA           IS 'Código de la empresa';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.CODCIA               IS 'Código de la compañía';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.VERSION              IS 'Número de versión del archivo auditado';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.ACCION               IS 'Acción realizada sobre el archivo (INSERT, UPDATE, DELETE)';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.CLV_DOCUMENTO_GRUPO  IS 'Clave del grupo de documentos';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.CLV_DOCUMENTO        IS 'Clave del tipo de documento';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.COMENTARIOS          IS 'Comentarios asociados al archivo';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.ARCHIVO_BLOB         IS 'Contenido binario del archivo';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.CREATED              IS 'Fecha de creación del registro de auditoría';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.CREATED_BY           IS 'Usuario que creó el registro de auditoría';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.UPDATED              IS 'Fecha de última modificación';
COMMENT ON COLUMN SICAS_OC.ARCHIVOS_POLIZAS_AUD.UPDATED_BY           IS 'Usuario que actualizó el registro';
